const deepFreeze = value => {
  if(value&&typeof value==='object'&&!Object.isFrozen(value)){
    for(const child of Object.values(value))deepFreeze(child);
    Object.freeze(value);
  }
  return value;
};
const freezeList = list => Object.freeze(list.map(item => deepFreeze(item)));
